describe('Element Manager Functionality', () => {
  it('should add and delete elements correctly', () => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
    cy.get('button[onclick="addElement()"]').click();
    cy.get('button[onclick="addElement()"]').click();
    cy.get('button[onclick="deleteElement(1)"]').click();
    cy.url().should('include', '/add_remove_elements/');
    cy.get('button[onclick="deleteElement(1)"]').click();
    cy.url().should('include', '/add_remove_elements/');
    cy.get('button[onclick="deleteElement(1)"]').click();
    cy.get('button[onclick="deleteElement(1)"]').should('be.visible');
  });

  it('should not change the URL when adding or deleting elements', () => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
    cy.get('button[onclick="addElement()"]').click();
    cy.url().should('include', '/add_remove_elements/');
    cy.get('button[onclick="deleteElement(1)"]').click();
    cy.url().should('include', '/add_remove_elements/');
  });
});
